import type { IncomingMessage, ServerResponse } from 'http';
// Load the esbuild bundle, not the TypeScript source tree (see api/webhooks/resend.ts for why).
// @ts-ignore - generated by `npm run build`
import { handleCoreApi } from '../../core-server.bundle.js';

export default async function handler(req: IncomingMessage & { body?: any }, res: ServerResponse) {
  try {
    const handled = await handleCoreApi(req, res);
    if (!handled && !res.writableEnded) {
      res.statusCode = 404;
      res.end();
    }
  } catch (error: any) {
    console.error('[Instagram OAuth callback] Failed:', error?.message || 'unknown error');
    if (!res.writableEnded) {
      res.statusCode = 500;
      res.setHeader('Content-Type', 'application/json');
      res.end(JSON.stringify({ error: 'Instagram authorization could not be completed.' }));
    }
  }
}
